/* Linked List Node structure */
struct node
{
    int data;
    struct node* next;
};

/* Circular Queue structure using Linked List */
struct Queue
{
    struct node *front, *rear;
};

/* Function to create a new node */
struct node* createNode(int data)
{
    struct node* new_node = (struct node*)malloc(sizeof(struct node));
    new_node->data = data;
    new_node->next = NULL;
    return new_node;
}

/* Function to create an empty queue */
struct Queue* createQueue()
{
    /* Allocate memory for Queue structure */
    struct Queue* queue = (struct Queue*)malloc(sizeof(struct Queue));

    /* Initialize front and rear pointers */
    queue->front = queue->rear = NULL;
    return queue;
}

/* Function to check if the queue is empty or not */
int isEmpty(struct Queue* queue)
{
    return (queue->front == NULL);
}

/* Function to add an item to the queue */
void enqueue(struct Queue* queue, int data)
{
    /* Create a new node */
    struct node* new_node = createNode(data);

    /* Check if the queue is empty */
    if (isEmpty(queue))
        queue->front = new_node;
    else
        queue->rear->next = new_node;

    /* Update rear pointer */
    queue->rear = new_node;

    /* Make the queue circular */
    queue->rear->next = queue->front;
}

/* Function to dequeue an item from the queue */
int dequeue(struct Queue* queue)
{
    /* Check if queue is empty */
    if (isEmpty(queue))
        return -1;

    /* Store front node, and move front pointer to next node */
    struct node* temp = queue->front;
    int data = temp->data;
    queue->front = queue->front->next;

    /* Make the queue circular */
    queue->rear->next = queue->front;

    /* Free the dequeued node */
    free(temp);

    return data;
}

/* Function to display the contents of queue */
void display(struct Queue* queue)
{
    struct node* temp = queue->front;
    printf("\nCircular Queue: ");
    if (isEmpty(queue))
        printf("Empty\n");
    else
    {
